#!/usr/bin/env node
/**
 * Copy the committed wasm-bindgen glue (`server/src/generated/**`) into the tsc
 * output tree (`server/out/generated/**`) so the compiled server can `require`
 * the `.wasm` + JS glue at runtime (tsc emits only `.ts` → `.js`; it never
 * copies the generated `.js`/`.wasm` assets). Run as `postbuild`.
 *
 * The glue itself is (re)generated by `npm run build:wasm` (cargo +
 * wasm-bindgen) whenever the Rust `sutra-lint-core` changes; it is committed, so
 * a plain `npm run build` only needs this copy.
 */
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const src = path.join(__dirname, '..', 'server', 'src', 'generated');
const dest = path.join(__dirname, '..', 'server', 'out', 'generated');

if (!fs.existsSync(src)) {
  console.error(
    `[copy-generated] missing ${src} — run \`npm run build:wasm\` to generate the WASM glue first`
  );
  process.exit(1);
}

fs.rmSync(dest, { recursive: true, force: true });
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.cpSync(src, dest, { recursive: true });
console.log(`[copy-generated] ${src} -> ${dest}`);
